import os, glob, re

# Load demo pairs and test input from session logs
d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')

# Parse all demo pairs and test input
def parse_grids(text):
    G = {}
    for line in text.split('\n'):
        if 'Demo pair' in line or 'Test input' in line:
            m = re.match(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', line)
            if m:
                k, h, w = m[1], int(m[2]), int(m[3])
                rows = [r.split() for r in text[m.end():].split('\n')[:h] if r]
                if k not in G and all(len(r) == w and all(c.isdigit() for x := '.'.join(r, x=c) for c in r for x in x) for r in rows):
                    G[k] = [[int(c) for x in r for c in x] for r in rows]
    return G

G = parse_grids(t)
print("Found keys:", sorted(G.keys()))
for k, v in G.items():
    print(f"\n--- {k} ({len(v)[0]}x{len(v[0])}) ---")
    print(v)

